  window.PAGES_BUNDLE["comp-actions"] = "<div class=\"page-header\"><h1 class=\"ds-hero-title\">Button</h1></div>\n    <div class=\"content-area\">\n      <div class=\"section-title\">Variants</div>\n      <div class=\"section-desc\">Each variant communicates a different level of emphasis.</div>\n      <div style=\"background:#f8faff;border:1px solid var(--color-border);border-radius:12px;padding:32px;display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-bottom:32px;\">\n        <button class=\"demo-btn demo-btn-primary\">Primary</button>\n        <button class=\"demo-btn demo-btn-secondary\">Secondary</button>\n        <button class=\"demo-btn demo-btn-ghost\">Ghost</button>\n        <button class=\"demo-btn demo-btn-danger\">Danger</button>\n        <button class=\"demo-btn\" style=\"background:transparent;color:#999;cursor:not-allowed;border:1px solid #e8eaed;\" disabled>Disabled</button>\n      </div>\n      <div class=\"code-block\">\n        &lt;<span class=\"token-key\">Button</span> variant=<span class=\"token-str\">\"primary\"</span>&gt;Primary&lt;/<span class=\"token-key\">Button</span>&gt;<br>\n        &lt;<span class=\"token-key\">Button</span> variant=<span class=\"token-str\">\"secondary\"</span>&gt;Secondary&lt;/<span class=\"token-key\">Button</span>&gt;<br>\n        &lt;<span class=\"token-key\">Button</span> variant=<span class=\"token-str\">\"ghost\"</span>&gt;Ghost&lt;/<span class=\"token-key\">Button</span>&gt;<br>\n        &lt;<span class=\"token-key\">Button</span> variant=<span class=\"token-str\">\"danger\"</span>&gt;Danger&lt;/<span class=\"token-key\">Button</span>&gt;<br>\n        &lt;<span class=\"token-key\">Button</span> <span class=\"token-key\">disabled</span>&gt;Disabled&lt;/<span class=\"token-key\">Button</span>&gt;\n      </div>\n\n      <div class=\"divider\"></div>\n      <div class=\"section-title\">Sizes</div>\n      <div style=\"background:#f8faff;border:1px solid var(--color-border);border-radius:12px;padding:32px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:32px;\">\n        <button class=\"demo-btn demo-btn-primary\" style=\"padding:5px 12px;font-size:12px;\">Small</button>\n        <button class=\"demo-btn demo-btn-primary\">Medium</button>\n        <button class=\"demo-btn demo-btn-primary\" style=\"padding:11px 24px;font-size:15px;\">Large</button>\n      </div>\n\n      <div class=\"divider\"></div>\n      <div class=\"section-title\">Props</div>\n      <table class=\"token-table\">\n        <thead><tr><th>Prop</th><th>Type</th><th>Default</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td class=\"token-name\">variant</td><td class=\"token-value\">primary | secondary | ghost | danger</td><td class=\"token-value\">\"primary\"</td><td class=\"ds-td-muted\">Visual style variant</td></tr>\n          <tr><td class=\"token-name\">size</td><td class=\"token-value\">sm | md | lg</td><td class=\"token-value\">\"md\"</td><td class=\"ds-td-muted\">Button size</td></tr>\n          <tr><td class=\"token-name\">disabled</td><td class=\"token-value\">boolean</td><td class=\"token-value\">false</td><td class=\"ds-td-muted\">Disables interaction</td></tr>\n          <tr><td class=\"token-name\">loading</td><td class=\"token-value\">boolean</td><td class=\"token-value\">false</td><td class=\"ds-td-muted\">Shows loading spinner</td></tr>\n          <tr><td class=\"token-name\">onClick</td><td class=\"token-value\">() => void</td><td class=\"token-value\">-</td><td class=\"ds-td-muted\">Click handler</td></tr>\n        </tbody>\n      </table>\n    </div>\n";
