  window.PAGES_BUNDLE["comp-navigation"] = "<div class=\"page-header\"><h1 class=\"ds-hero-title\">Navigation</h1></div>\n<div class=\"content-area\">\n  <p style=\"color:var(--color-text-muted);\">Select a component from the sidebar to view its documentation.</p>\n</div>\n";
  window.PAGES_BUNDLE["components"] = "<div class=\"page-header\"><h1 class=\"ds-hero-title\">Component Library</h1></div>\n    <div class=\"content-area\">\n      <div class=\"section-title\">Actions</div>\n      <div class=\"section-desc\">Interactive elements for triggering operations and navigation.</div>\n      <div class=\"grid-3\" style=\"margin-bottom:32px;\">\n        <div class=\"component-card\" onclick=\"navigate('comp-actions')\">\n          <div class=\"component-preview\"><div style=\"display:flex;gap:8px;flex-wrap:wrap;justify-content:center;\"><button class=\"demo-btn demo-btn-primary\">Primary</button><button class=\"demo-btn demo-btn-secondary\">Secondary</button><button class=\"demo-btn demo-btn-ghost\">Ghost</button></div></div>\n          <div class=\"component-info\"><h4>Button</h4><p>Trigger actions and navigation</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"display:flex;gap:8px;align-items:center;\"><div class=\"demo-toggle\"></div><div class=\"demo-toggle\" style=\"background:#e8eaed;\"><div style=\"content:'';position:absolute;\"></div></div></div></div>\n          <div class=\"component-info\"><h4>Toggle</h4><p>Binary on/off state switcher</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"display:flex;gap:10px;align-items:center;\"><div class=\"demo-checkbox\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 12 12\" fill=\"none\"><polyline points=\"2 6 5 9 10 3\" stroke=\"white\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div><div style=\"width:18px;height:18px;border-radius:4px;border:2px solid var(--color-border);\"></div></div></div>\n          <div class=\"component-info\"><h4>Checkbox</h4><p>Single or multiple selection</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n      </div>\n\n      <div class=\"section-title\">Display</div>\n      <div class=\"section-desc\">Non-interactive elements for presenting information.</div>\n      <div class=\"grid-3\" style=\"margin-bottom:32px;\">\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"display:flex;gap:6px;flex-wrap:wrap;justify-content:center;\"><span class=\"demo-badge demo-badge-blue\">New</span><span class=\"demo-badge demo-badge-green\">Stable</span><span class=\"demo-badge demo-badge-red\">Error</span></div></div>\n          <div class=\"component-info\"><h4>Badge</h4><p>Status labels and counts</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"display:flex;gap:8px;\"><div class=\"demo-avatar\" style=\"background:#1852FE;\">AP</div><div class=\"demo-avatar\" style=\"background:#22c55e;\">MK</div><div class=\"demo-avatar\" style=\"background:#f59e0b;\">JD</div></div></div>\n          <div class=\"component-info\"><h4>Avatar</h4><p>User identity representation</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"background:white;border:1px solid var(--color-border);border-radius:8px;padding:16px;width:180px;box-shadow:0 2px 8px rgba(0,0,0,0.08);\"><div style=\"font-size:13px;font-weight:600;color:var(--color-dark);margin-bottom:4px;\">Card Title</div><div style=\"font-size:12px;color:var(--color-text-muted);\">Card description here</div></div></div>\n          <div class=\"component-info\"><h4>Card</h4><p>Content container surface</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n      </div>\n\n      <div class=\"section-title\">Forms & Inputs</div>\n      <div class=\"section-desc\">Data collection components with validation and accessibility built in.</div>\n      <div class=\"grid-3\" style=\"margin-bottom:32px;\">\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><input class=\"demo-input\" placeholder=\"Enter text...\" /></div>\n          <div class=\"component-info\"><h4>Text Input</h4><p>Single-line text entry</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><select style=\"padding:8px 12px;font-size:13.5px;border:1px solid var(--color-border);border-radius:6px;background:white;color:var(--color-text);font-family:var(--font-sans);outline:none;cursor:pointer;\"><option>Select option</option><option>Option A</option><option>Option B</option></select></div>\n          <div class=\"component-info\"><h4>Select</h4><p>Dropdown option picker</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><textarea style=\"padding:8px 12px;font-size:13px;border:1px solid var(--color-border);border-radius:6px;font-family:var(--font-sans);color:var(--color-text);outline:none;resize:none;width:180px;height:64px;\" placeholder=\"Multi-line text...\"></textarea></div>\n          <div class=\"component-info\"><h4>Textarea</h4><p>Multi-line text entry</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n      </div>\n\n      <div class=\"section-title\">Feedback</div>\n      <div class=\"section-desc\">Communicate system status and guide user actions.</div>\n      <div class=\"grid-3\">\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"background:#e6f9f0;border:1px solid #a7f0c8;border-radius:8px;padding:12px 16px;display:flex;align-items:center;gap:10px;width:180px;\"><span style=\"font-size:16px;\">✓</span><div><div style=\"font-size:12.5px;font-weight:600;color:#1a8a4a;\">Success</div><div style=\"font-size:11.5px;color:#2d9e5f;\">Operation complete</div></div></div></div>\n          <div class=\"component-info\"><h4>Alert</h4><p>Inline status messages</p><div class=\"tag-row\"><span class=\"tag-pill tag-stable\">Stable</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"position:relative;display:inline-block;\"><div style=\"width:36px;height:8px;background:#e8eaed;border-radius:100px;overflow:hidden;\"><div style=\"width:60%;height:100%;background:var(--color-primary);border-radius:100px;\"></div></div><div style=\"font-size:11px;color:var(--color-text-muted);margin-top:6px;text-align:center;\">60%</div></div></div>\n          <div class=\"component-info\"><h4>Progress</h4><p>Task completion indicator</p><div class=\"tag-row\"><span class=\"tag-pill tag-beta\">Beta</span></div></div>\n        </div>\n        <div class=\"component-card\">\n          <div class=\"component-preview\"><div style=\"background:white;border:1px solid var(--color-border);border-radius:8px;padding:12px 16px;box-shadow:0 4px 16px rgba(0,0,0,0.12);width:180px;font-size:13px;\">Toast notification</div></div>\n          <div class=\"component-info\"><h4>Toast</h4><p>Transient status messages</p><div class=\"tag-row\"><span class=\"tag-pill tag-beta\">Beta</span></div></div>\n        </div>\n      </div>\n    </div>\n";
  window.PAGES_BUNDLE["form-scrollable"] = "<div class=\"page-header\"><h1 class=\"ds-hero-title\">Scrollable Form</h1></div>\n<div class=\"content-area\">\n  <div class=\"ds-card ds-coming-soon\">Scrollable Form documentation coming soon</div>\n</div>\n";
